def require(value,message):
    if not value:raise ValueError(message)
def source(collection,filename):return next(s for s in SOURCES if s['collectionId']==collection and s['filename']==filename)
def locked(input_root,s):
    raw=(input_root/s['collectionId']/s['filename']).read_bytes()
    require(hashlib.sha256(raw).hexdigest()==s['sha256'],'Original source hash changed: '+s['filename'])
    return raw
def number(text):
    require(re.fullmatch(r'-?\d+(?:\.\d+)?',str(text)) is not None,'Unknown source numeric token')
    n=Decimal(str(text));require(n.is_finite(),'Non-finite source value')
    return n
def scalar(value):
    return int(value) if value==value.to_integral_value() else float(value)
def rows_csv(raw):
    return list(csv.DictReader(io.StringIO(raw.decode('utf-8-sig'))))
def workbook(raw,sheet_name):
    with ZipFile(io.BytesIO(raw)) as z:
        strings=[''.join(x.itertext()) for x in ET.fromstring(z.read('xl/sharedStrings.xml')).findall('m:si',NS)] if 'xl/sharedStrings.xml' in z.namelist() else []
        rels={r.attrib['Id']:r.attrib['Target'] for r in ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))}
        sh=next(s for s in ET.fromstring(z.read('xl/workbook.xml')).findall('m:sheets/m:sheet',NS) if s.attrib['name']==sheet_name)
        target=rels[sh.attrib[REL]];target=target.lstrip('/') if target.startswith('/') else posixpath.normpath('xl/'+target)
        grid=[]
        for r in ET.fromstring(z.read(target)).findall('m:sheetData/m:row',NS):
            values={}
            for c in r.findall('m:c',NS):
                v=c.find('m:v',NS);text=v.text if v is not None and v.text is not None else ''
                if c.get('t')=='s':text=strings[int(text)] if text else ''
                elif c.get('t')=='inlineStr':text=''.join(c.find('m:is',NS).itertext())
                values[c.attrib['r']]=text
            grid.append((int(r.attrib['r']),values))
        return grid
def column(key,label,numeric=False,unit=None):
    d=dict(key=key,label=label,type='number' if numeric else 'text')
    if unit:d['unit']=unit
    return d
def dataset(id,title,description,s,rows,columns,metric,notes,time=None,url=None):
    d=dict(id=id,title=title,description=description,topic='Research context',geography='institution',status='observed',timeLabel='Historical source extract',sourceName=title,sourceUrl=url or 'https://open.canada.ca/',datasetId=s['datasetId'],tableName='; '.join(t['tableName'] for t in s['tables']),notes=notes,columns=columns,rows=rows,defaultMetric=metric,entityField='comparator')
    if time:d['timeField']=time
    return d
def cihr_expectation_review(dictionary_raw,quarter_raw):
    dictionary=workbook(dictionary_raw,'EN-Metadata')
    definitions={cells.get('B'+str(row)):dict(sourceExcelRow=row,definition=cells.get('C'+str(row)),notes=cells.get('F'+str(row))) for row,cells in dictionary if cells.get('B'+str(row)) in ['AmountPaidFY_MontantPayeAF','TotalAmountPaid_MontantTotalPaye','TotalAmountAwarded_MontantTotalAccorde','FiscalYear_AnneeFinanciere','InstitutionPaidCode_CodeEtablissementPaye'] and row<40}
    require('In the Q1-Q3 updates, this field will only report the expected amount to be paid in the current fiscal year.' in definitions['AmountPaidFY_MontantPayeAF']['notes'],'CIHR expectation definition changed')
    require('YYYYYY' in definitions['FiscalYear_AnneeFinanciere']['notes'] and 'April 1st to March 31st' in definitions['FiscalYear_AnneeFinanciere']['notes'],'CIHR fiscal-year definition changed')
    grid=workbook(quarter_raw,'G&A_S&B');require(len(grid)==7310,'CIHR Q3 original row coverage changed')
    header=grid[0][1]
    selected={'B':'FiscalYear_AnneeFinanciere','C':'FundingReferenceNumber_NumeroReferenceFinancement','G':'InstitutionPaidNameEN_NomEtablissementPayeAN','I':'InstitutionPaidCode_CodeEtablissementPaye','AA':'AmountPaidFY_MontantPayeAF'}
    require(all(header.get(col+'1')==name for col,name in selected.items()),'CIHR Q3 scientific header changed')
    aliases={'Dalhousie University (Nova Scotia)':('Dalhousie / Halifax','CHAA'),'Lakehead University (Thunder Bay, Ontario)':('Lakehead / Thunder Bay','CEJA'),'McMaster University':('McMaster / Hamilton','CEBA'),'University of British Columbia':('UBC / Vancouver','CAAA'),'University of Calgary':('Calgary / Calgary','CBBA'),'University of Northern British Columbia':('UNBC / Prince George','ADQW'),'University of Saskatchewan':('USask / Saskatoon','CCAA')}
    groups=collections.defaultdict(list);seen=set();blank=0
    for row,cells in grid[1:]:
        year=cells.get('B'+str(row));frn=cells.get('C'+str(row));code=cells.get('I'+str(row));name=cells.get('G'+str(row));amount=cells.get('AA'+str(row),'')
        require(year=='202526' and frn and code,'CIHR Q3 fiscal/reference/institution key missing or changed')
        key=(code,year,frn);require(key not in seen,'CIHR Q3 duplicate paid-institution/fiscal/reference key');seen.add(key)
        blank+=int(amount=='')
        require(amount=='','CIHR Q3 expected-amount availability changed; review before release')
        if name in aliases:
            comparator,expected_code=aliases[name];require(code==expected_code,'CIHR paid-institution alias/code changed')
            groups[name].append(row)
    require(set(groups)==set(aliases),'CIHR reviewed institution source coverage changed')
    return dict(status='blocked',proposedDatasetId='cihr-expected-payments',sourceFiscalYear='202526',periodLabel='2025–2026',snapshotQuarter='Q3',sourceRows=len(grid)-1,uniquePaidInstitutionFiscalReferenceKeys=len(seen),expectedAmountPresentRows=0,expectedAmountBlankRows=blank,otherAmountFields=[dict(column=col,sourceField=field,presentRows=sum(bool(cells.get(col+str(row),'')) for row,cells in grid[1:]),notSubstituted=True) for col,field in [('AB','TotalAmountPaid_MontantTotalPaye'),('AC','TotalAmountAwarded_MontantTotalAccorde')]],definitions=definitions,selectedSourceFields=list(selected.values()),institutionCoverage=[dict(comparator=aliases[name][0],sourceInstitutionName=name,sourceInstitutionCode=aliases[name][1],fundingRecords=len(rows),sourceExcelRows=rows) for name,rows in sorted(groups.items())],reason='Every AmountPaidFY_MontantPayeAF source value is blank. The Q1–Q3 dictionary defines expected fiscal-year amounts, but this collected workbook contains none. TotalAmountPaid and TotalAmountAwarded are different measures and are not substituted; no amounts are converted to zero or inferred.')

def prepare(input_root):
    from nhhr_mapping_connections import connect_reviewed_geography
    datasets=[];bindings={};quality=[]
    locations=json.loads((ROOT/'src/atlas/institutionLocations.json').read_text());labels={l['comparator'] for l in locations}
    require(all(v['comparator'] in labels for v in INSTITUTIONS.values()),'Reviewed institutional context crosswalk changed')
    geography_note='Reviewed campus points locate whole-institution records for context. No amount, work count or infrastructure project is allocated to that campus, nearby residents, a health area, a future NHHR building or a specific facility.'
    # CFI: original grid rows, excluding all personal leader/member fields.
    cfi_source=source('DATA-C039','cfi_funded_projects_dataset_en_2026-03-13.xlsx')
    grid=workbook(locked(input_root,cfi_source),'Page1_1')
    require(len(grid)==14039,'CFI original grid coverage changed')
    header=grid[0][1]
    require([header.get(c+'1') for c in ['I','K','M','O']]==['Lead Institution','Field of Research - Division','Decision Year','CFI Contribution'],'CFI scientific header changed')
    annual=collections.defaultdict(lambda:dict(project_records=0,cfi_contribution_cad=Decimal(0),medical_health_life_project_records=0,medical_health_life_contribution_cad=Decimal(0),source_rows=[]))
    for row,cells in grid[1:]:
        name=cells.get('I'+str(row),'')
        require(name!='','CFI source row missing lead institution')
        if name not in CFI:continue
        year=cells.get('M'+str(row),'');require(re.fullmatch(r'20\d\d|199[89]',year) is not None and int(year)<=2025,'CFI decision year outside reviewed scope')
        amount=number(cells.get('O'+str(row),''));require(amount>=0,'Negative CFI contribution needs review')
        a=annual[(name,year)];a['project_records']+=1;a['cfi_contribution_cad']+=amount;a['source_rows'].append(row)
        if cells.get('K'+str(row))==MEDICAL:a['medical_health_life_project_records']+=1;a['medical_health_life_contribution_cad']+=amount
    cfi_rows=[]
    for (name,year),a in sorted(annual.items()):
        cfi_rows.append(dict(comparator=CFI[name],source_lead_institution=name,decision_year=year,**{k:scalar(v) if isinstance(v,Decimal) else v for k,v in a.items() if k!='source_rows'}))
    totals=[]
    for name,comparator in sorted(CFI.items()):
        matching=[r for r in cfi_rows if r['source_lead_institution']==name]
        count=sum(r['project_records'] for r in matching);amount=sum(r['cfi_contribution_cad'] for r in matching)
        require((count,amount)==CFI_ORACLE[name],'CFI primary totals differ from independently recorded comparator summary')
        totals.append(dict(comparator=comparator,source_lead_institution=name,project_records=count,cfi_contribution_cad=amount,medical_health_life_project_records=sum(r['medical_health_life_project_records'] for r in matching),medical_health_life_contribution_cad=sum(r['medical_health_life_contribution_cad'] for r in matching),first_decision_year=min(r['decision_year'] for r in matching),latest_decision_year=max(r['decision_year'] for r in matching)))
    cfi_notes=[
      'Source is the complete collected CFI funded-project workbook dated 13 March 2026: 14,038 source rows plus one header. Only exact lead-institution matches enter these seven comparator extracts; collaborators are not assigned a share of the lead contribution.',
      'CFI contribution is the recorded infrastructure contribution, grouped by decision year. It is not total project cost, annual cash paid, institutional research income or an NHHR benefit. Values are nominal Canadian dollars; the source workbook has no separate currency field, and CFI Canadian-dollar reporting context is documented in the cited policy guide.',
      'Project records count original source rows. The workbook supplies no stable project-ID column; no assertion of unique underlying grants is made, and similarly named records are not collapsed or silently deduplicated.',
      'The medical subset uses the publisher exact division label Medical, health and life sciences. It includes life sciences and is not an independently adjudicated clinical/health-only portfolio.',
      'Unobserved institution/year combinations are not synthesized as zero rows. No NOSM lead-institution record is added. McMaster has valid source records but no reviewed campus point in this Atlas; it remains in chart/table/CSV without a geographic match.',
      geography_note]
