def fetch(url,headers):
    require(url.startswith(HOST+'/api/'),'Refresh URL outside reviewed authorized API')
    with urllib.request.urlopen(urllib.request.Request(url,headers=headers),timeout=90) as r:return r.read()
def refresh(input_root,headers):
    manifest=json.loads(fetch(MANIFEST,headers));resources={r['id']:r for r in manifest['resources'] if r.get('kind')=='dataset'}
    for did in sorted({s['datasetId'] for s in SOURCES}):
        require(did in resources and resources[did].get('available'),'Reviewed dataset unavailable')
        r=resources[did];require(r['datasetUrl']=='/api/datasets/'+did,'Dataset endpoint changed')
        descriptor=json.loads(fetch(HOST+r['datasetUrl'],headers))['dataset']
        require(descriptor['id']==did and descriptor['status']=='ready' and descriptor['artifactVersion']==1,'Dataset identity/version changed')
    cat=next(r for r in manifest['manifestSources'] if r['id']==CATALOGUE);links={f['name']:f['url'] for f in cat['files']}
    files=rows_csv(fetch(HOST+links['NHHR_files.csv'],headers));tables=rows_csv(fetch(HOST+links['NHHR_tables.csv'],headers))
    for s in SOURCES:
        matches=[r for r in files if r['dataset_id']==s['datasetId'] and r['canonical_relative_path']==s['sourceRelativePath']]
        require(any(r['sha256']==s['sha256'] and r['original_file_ids'].split(';')==s['originalFileIds'] for r in matches),'Original file ID/hash lock changed')
        for t in s['tables']:
            matches=[r for r in tables if r['dataset_id']==s['datasetId'] and r['table_name']==t['tableName']]
            require(len(matches)==1 and matches[0]['source_sha256']==s['sha256'] and matches[0]['parquet_sha256']==t['parquetSha256'] and int(matches[0]['row_count'])==t['rows'],'Scientific table lineage changed')
    def download(s):
        raw=b''.join(fetch(HOST+'/api/files/'+ident+'/download',headers) for ident in s['originalFileIds'])
        require(hashlib.sha256(raw).hexdigest()==s['sha256'],'Downloaded original/multipart hash differs')
        p=input_root/s['collectionId']/s['filename'];p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(raw)
    with ThreadPoolExecutor(max_workers=4) as pool:list(pool.map(download,SOURCES))
def emit(path,value,check):
    content=(json.dumps(value,indent=2,ensure_ascii=False,allow_nan=False)+'\n').encode()
    if check:require(path.exists() and path.read_bytes()==content,str(path.relative_to(ROOT))+': generated output drift')
    else:path.parent.mkdir(parents=True,exist_ok=True);path.write_bytes(content)
def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--input',type=pathlib.Path,required=True);p.add_argument('--refresh',action='store_true');p.add_argument('--check',action='store_true');p.add_argument('--headers-file',type=pathlib.Path);args=p.parse_args()
    if args.refresh:refresh(args.input,json.loads(args.headers_file.read_text()) if args.headers_file else {})
    release,provenance=prepare(args.input)
    emit(ROOT/'src/atlas/snapshots/research-expansion.json',release,args.check);emit(ROOT/'public/data/nhhr/research-expansion.json',release,args.check);emit(ROOT/'public/data/nhhr/research-expansion-provenance.json',provenance,args.check)
    print(json.dumps(release['snapshot']))
if __name__=='__main__':main()
